#!/bin/bash

#SBATCH -c 10
#SBATCH -t 04:00:00
#SBATCH --mail-user=nme3923@nyu.edu
#SBATCH --mail-type=END,FAIL

#Activate your environments here
source ~/.bashrc
source /share/apps/NYUAD5/miniconda/3-4.11.0/bin/activate
conda activate /scratch/nme3923/conda-envs/myenviro

#Loading File as myenviro contains PLINK.

# Removes duplicate individuals and duplicate variants from a PLINK fileset and
# writes a new .bed/.bim/.fam (the .bed is regenerated by PLINK, so it matches).
# The input fileset is never modified.
#
# Duplicate individuals: rows sharing the same IID (column 2 of .fam).
#     The copy with the LOWEST missing-genotype rate is kept (ties -> first row).
# Duplicate variants   : rows sharing the same ID (column 2 of .bim), OR the
#     same chromosome + position + allele pair (alleles in either order).
#     The FIRST occurrence is kept.
#
# Usage: sbatch remove_duplicates.sh <input_prefix> <output_prefix>
#   prefixes may be paths in any directory (no .bed/.bim/.fam)
# Lists of what was removed are written to <output_prefix>.removed_individuals.txt
# and <output_prefix>.removed_variants.txt

set -euo pipefail

if [ "$#" -ne 2 ]; then
	echo "Usage: $0 <input_prefix> <output_prefix>" >&2
	exit 1
fi

strip_ext() { local f=${1%.bed}; f=${f%.bim}; f=${f%.fam}; echo "$f"; }
abspath() { local d; d=$(cd "$(dirname "$1")" && pwd) && echo "${d}/$(basename "$1")"; }

IN=$(strip_ext "$1")
OUT=$(strip_ext "$2")
mkdir -p "$(dirname "$OUT")"
IN=$(abspath "$IN")
OUT=$(abspath "$OUT")

for ext in bed bim fam; do
	[ -s "${IN}.${ext}" ] || { echo "ERROR: ${IN}.${ext} not found" >&2; exit 1; }
done
[ "$IN" != "$OUT" ] || { echo "ERROR: output prefix must differ from input" >&2; exit 1; }

tmp=$(mktemp -d "${OUT}.tmp.XXXXXX")
trap 'rm -rf "$tmp"' EXIT

# ---- Step 1: give every repeated ID a unique temporary name ----------------
# (PLINK itself refuses to load duplicate IIDs, and --remove/--exclude act on
#  names, so repeats must be distinguishable.)  First occurrence keeps its name.
ln -s "${IN}.bed" "${tmp}/w.bed"

awk 'BEGIN{FS=OFS="\t"}
     NF!=6 {print "ERROR: bim line " NR " has " NF " columns" > "/dev/stderr"; exit 1}
     { key=$1":"$4":"(($5<$6)?$5"/"$6:$6"/"$5)
       if ($2 in id || key in pos) {
           orig=$2; $2=$2"__dup"NR
           print $2 > "'"${tmp}"'/dupvars.txt"
           print NR, orig, $2 > "'"${tmp}"'/dupvars.map"
       } else { id[$2]=1; pos[key]=1 }
       print }' "${IN}.bim" > "${tmp}/w.bim"
touch "${tmp}/dupvars.txt" "${tmp}/dupvars.map"

awk '{ if ($2 in seen) $2=$2"__dup"NR; else seen[$2]=1; print }' "${IN}.fam" > "${tmp}/w.fam"

# ---- Step 2: pick which copy of each duplicated individual to keep ---------
plink --bfile "${tmp}/w" --missing --allow-no-sex --out "${tmp}/miss"

# w.fam row i  <->  miss.imiss data row i (same order). Keep the lowest F_MISS.
# Kept copy gets its original IID back; every dropped copy gets a unique
# __dropN name (so a kept later copy never collides with a dropped earlier one).
paste -d' ' <(awk '{print $2}' "${IN}.fam") <(awk 'NR>1{print $6}' "${tmp}/miss.imiss") |
awk '{ n++; orig[n]=$1; f[n]=$2
       if (!($1 in best) || f[n] < f[best[$1]]) best[$1]=n }
     END { for (i=1;i<=n;i++) print i, (best[orig[i]]==i ? orig[i] : orig[i]"__drop"i) }' > "${tmp}/names.map"

awk 'NR==FNR { nm[$1]=$2; next } { $2=nm[FNR]; print }' "${tmp}/names.map" "${tmp}/w.fam" > "${tmp}/w2.fam"
mv "${tmp}/w2.fam" "${tmp}/w.fam"

# --remove wants FID IID
awk '$2 ~ /__drop[0-9]+$/ {print $1, $2}' "${tmp}/w.fam" > "${tmp}/remove.txt"

# ---- Step 3: remove and write the new bed/bim/fam --------------------------
plink --bfile "${tmp}/w" \
	--remove "${tmp}/remove.txt" \
	--exclude "${tmp}/dupvars.txt" \
	--allow-no-sex --make-bed --out "${OUT}"

# ---- Reports + verification ------------------------------------------------
nind=$(wc -l < "${tmp}/remove.txt")
nvar=$(wc -l < "${tmp}/dupvars.txt")
awk '{print $1, $2}' "${tmp}/remove.txt" | sed 's/__drop[0-9]*$//' > "${OUT}.removed_individuals.txt"
cut -d' ' -f1,2 "${tmp}/dupvars.map" > "${OUT}.removed_variants.txt"

[ "$(wc -l < "${OUT}.fam")" -eq $(( $(wc -l < "${IN}.fam") - nind )) ] || { echo "ERROR: fam row count mismatch" >&2; exit 1; }
[ "$(wc -l < "${OUT}.bim")" -eq $(( $(wc -l < "${IN}.bim") - nvar )) ] || { echo "ERROR: bim row count mismatch" >&2; exit 1; }
[ "$(cut -f2 "${OUT}.bim" | sort | uniq -d | wc -l)" -eq 0 ] || { echo "ERROR: duplicate variant IDs remain" >&2; exit 1; }
[ "$(awk '{print $2}' "${OUT}.fam" | sort | uniq -d | wc -l)" -eq 0 ] || { echo "ERROR: duplicate IIDs remain" >&2; exit 1; }

echo "done: removed ${nind} duplicate individual(s) and ${nvar} duplicate variant(s)"
echo "      individuals: $(wc -l < "${IN}.fam") -> $(wc -l < "${OUT}.fam")"
echo "      variants   : $(wc -l < "${IN}.bim") -> $(wc -l < "${OUT}.bim")"
